import { Audio } from "@remotion/media";
import React from "react";
import { interpolate, staticFile, useCurrentFrame } from "remotion";
import { Scene } from "./Scene";
import { CUTS, CutName } from "./timeline";
import { AlphaCtx, PlayCtx, PlayWin, POSTS, PostKey } from "./ui/Post";

const playFor = (cut: CutName): Record<string, PlayWin> =>
  Object.fromEntries((Object.entries(CUTS[cut].MEDIA) as [PostKey, PlayWin][]).map(([k, w]) => [POSTS[k].id, w]));

// SFX stem per cut, generated by sfx.py from the same beats file
const SFX: Record<CutName, string> = { v12: "sfx_stem.wav", v9s: "sfx_stem_9s.wav", v6s: "sfx_stem_6s.wav" };

// The whole Twitter-feed montage. Background stays black here (preview);
// the alpha render drops it.
export const Montage: React.FC<{ transparent?: boolean; cut?: CutName }> = ({ transparent = false, cut = "v12" }) => {
  const f = useCurrentFrame();
  return (
    <PlayCtx.Provider value={playFor(cut)}>
      <AlphaCtx.Provider value={transparent}>
        <Scene s={CUTS[cut].stateAt(f)} />
      </AlphaCtx.Provider>
      {/* SFX stem (sfx.py): whooshes driven by the scroll curve, soft ticks on highlights */}
      <Audio src={staticFile(SFX[cut])} />
      {/* line 10 of the VO from his current version (cut before line 11 starts) */}
      <Audio src={staticFile("vo_line10.wav")} volume={(t) => interpolate(t, [0, 70, 80], [1, 1, 0], { extrapolateRight: "clamp" })} />
    </PlayCtx.Provider>
  );
};
